#!/usr/bin/env python3
"""Compile the outputs of the next-steps experiments into iter2/NEXT_STEPS_RESULTS.md (numbers and captions only; interpretation is written separately).

Reads results/blob_split.json, REFINE_FULL_REPORT.md and the text files the queue wrote under jobs/. A missing input is reported, not hidden.
Usage: python make_next_report.py
"""
import json
from pathlib import Path

out = ["# Next-steps experiments: compiled results\n",
       "Generated by `make_next_report.py`. Every table below is the unedited output of the script named in its caption. "
       "Ground truth is CARLA v3 (917 vehicles visible from Rec1 with >= 80 px at 960x540); 'recall' is a ground-truth match at the stated IoU.\n"]


def section(title, fn):
    out.append(f"\n## {title}\n")
    try:
        fn()
    except Exception as e:
        out.append(f"_not available: {type(e).__name__}: {e}_\n")


def block(path, caption):
    noise = ("Loading weights", "Warning: You are sending", "LOAD REPORT", "UNEXPECTED", "MISSING", "Notes:", "model.pixel_level_module",
             "python.exe -u ", "\x1b[", "Status     |")
    keep = [l for l in Path(path).read_text(encoding="utf-8", errors="replace").splitlines()
            if l.strip() and not any(n in l for n in noise) and not l.startswith("-----") and not (l.startswith("Key ") and "|" in l)]
    text = "\n".join(keep).strip()
    out.append(caption + "\n")
    out.append("```")
    out.append(text)
    out.append("```\n")


def blob_split():
    d = json.loads(Path("results/blob_split.json").read_text())
    out.append(f"`blob_split.py`: can the transmitted segmentation + edge map separate touching vehicles? {d['n_gt']} ground-truth vehicles, cam1, all 112 v3 cases; "
               "scored by box matching at IoU 0.5. All settings tried on the same cases (a sweep: the best rows are optimistic).\n")
    out.append("| method | recall @0.5 | recall @0.3 | precision @0.5 | <24 px | 24-48 px | 48-120 px | >120 px | recall of merged-blob vehicles | count MAE | count bias |")
    out.append("|---|---|---|---|---|---|---|---|---|---|---|")
    for r in d["results"]:
        b = r["bins"]
        out.append(f"| {r['method']} | {r['recall5']:.2f} | {r['recall3']:.2f} | {r['precision5']:.2f} | " + " | ".join(f"{b[k]:.2f}" for k in ("<24 px", "24-48 px", "48-120 px", ">120 px")) +
                   f" | {r['merged']:.2f} | {r['count_mae']:.2f} | {r['count_bias']:+.2f} |")
    out.append("")


section("1. Splitting merged blobs with the existing payload", blob_split)
section("2. Crop method (prompt_refine) on every case", lambda: out.append(Path("REFINE_FULL_REPORT.md").read_text(encoding="utf-8")))
section("3. Generation at 2048x1152 (v3 cases 1-24)", lambda: block("jobs/gt_eval_2048.txt", "`gt_eval.py`, default 1024x576 vs 2048x1152, same 24 cases, same seed:"))
section("4. Sender segmenter at higher input resolution", lambda: block("jobs/seg_resolution.txt", "`seg_resolution.py`:"))
section("5. Sender-side instance segmentation and detectors", lambda: block("jobs/instance_sender.txt", "`instance_sender.py`:"))
section("6. Receiver hyperparameter sweep", lambda: block("jobs/hp_sweep.txt", "`hp_sweep.py` (sweep on cases 1-24, hold-out on 25-60 for the best configuration if it beats the default by >= 0.02 recall):"))
section("7. Training data", lambda: block("jobs/training_prep.txt", "`training_prep.py`:"))
Path("NEXT_STEPS_RESULTS.md").write_text("\n".join(out), encoding="utf-8")
print("wrote NEXT_STEPS_RESULTS.md,", len(out), "lines")
